"""Acquire the official CrisisBench v1.0 consolidated English humanitarian files.

Search order:
  1. TSVs already extracted under data/raw/crisisbench_official/
  2. crisis_datasets_benchmarks_v1.0.tar.gz under REPRO_DATA_CACHE (shared across runs)
  3. download from a public mirror into REPRO_DATA_CACHE, then extract

Hard gates: exact split sizes (61,164 / 8,935 / 17,356) and 11 labels.
Writes data/manifest.json with provenance; raises RuntimeError on mismatch.
"""
import csv
import hashlib
import json
import tarfile
from pathlib import Path

import pandas as pd
import requests

from . import config

SPLIT_FILES = {"train": "train.tsv", "development": "development.tsv", "test": "test.tsv"}
RAW_OUT = config.RAW_DIR / "crisisbench_official"


def _sha256(path: Path) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1 << 20), b""):
            h.update(chunk)
    return h.hexdigest()


def _archive_candidates():
    cands = []
    if config.CACHE_DIR:
        cands += [
            config.CACHE_DIR / "crisisbench_official" / config.OFFICIAL_ARCHIVE,
            config.CACHE_DIR / config.OFFICIAL_ARCHIVE,
        ]
    cands.append(config.RAW_DIR / config.OFFICIAL_ARCHIVE)
    return cands


def _download(dest: Path) -> Path:
    dest.parent.mkdir(parents=True, exist_ok=True)
    errors = []
    for url in config.OFFICIAL_URLS:
        try:
            with requests.get(url, stream=True, timeout=180, allow_redirects=True) as r:
                r.raise_for_status()
                tmp = dest.with_suffix(".part")
                with open(tmp, "wb") as f:
                    for chunk in r.iter_content(1 << 20):
                        if chunk:
                            f.write(chunk)
            with tarfile.open(tmp, "r:gz") as tf:
                names = set(tf.getnames())
                missing = [m for m in config.OFFICIAL_MEMBERS.values() if m not in names]
            if missing:
                raise RuntimeError(f"archive missing members: {missing}")
            tmp.replace(dest)
            return dest
        except Exception as e:  # noqa: BLE001 - collect and try next mirror
            errors.append(f"{url}: {e}")
    raise RuntimeError("All download mirrors failed:\n" + "\n".join(errors))


def _extract(archive: Path) -> None:
    RAW_OUT.mkdir(parents=True, exist_ok=True)
    with tarfile.open(archive, "r:gz") as tf:
        for split, member in config.OFFICIAL_MEMBERS.items():
            src = tf.extractfile(member)
            if src is None:
                raise RuntimeError(f"missing member {member} in {archive}")
            with open(RAW_OUT / SPLIT_FILES[split], "wb") as f:
                while True:
                    chunk = src.read(1 << 20)
                    if not chunk:
                        break
                    f.write(chunk)


def _read_split(path: Path) -> pd.DataFrame:
    return pd.read_csv(path, sep="\t", quoting=csv.QUOTE_NONE, dtype=str, keep_default_na=False)


def _validate(dfs):
    problems = []
    for split, expected in [("train", config.EXPECTED["train"]),
                            ("development", config.EXPECTED["development"]),
                            ("test", config.EXPECTED["test"])]:
        if len(dfs[split]) != expected:
            problems.append(f"{split}: expected {expected} records, got {len(dfs[split])}")
    labels = sorted({l for df in dfs.values() for l in df["class_label"].str.strip().unique()})
    if len(labels) != config.N_LABELS:
        problems.append(f"expected {config.N_LABELS} labels, got {len(labels)}: {labels}")
    required = {"id", "event", "source", "text", "lang", "lang_conf", "class_label"}
    for split, df in dfs.items():
        missing = required - set(df.columns)
        if missing:
            problems.append(f"{split}: missing columns {sorted(missing)}")
    return problems, labels


def ensure_data() -> dict:
    """Make the three split TSVs available and validated; return the manifest."""
    manifest = {"dataset": "CrisisBench v1.0 English humanitarian classification",
                "source": None, "archive_sha256": None}
    if all((RAW_OUT / f).exists() for f in SPLIT_FILES.values()):
        manifest["source"] = f"workspace:{RAW_OUT}"
    else:
        archive = next((p for p in _archive_candidates() if p.exists()), None)
        if archive is None:
            dest_root = config.CACHE_DIR if config.CACHE_DIR else config.RAW_DIR
            archive = _download(dest_root / "crisisbench_official" / config.OFFICIAL_ARCHIVE)
            manifest["source"] = f"downloaded:{archive}"
        else:
            manifest["source"] = f"cache:{archive}"
        manifest["archive_sha256"] = _sha256(archive)
        _extract(archive)
    dfs = {split: _read_split(RAW_OUT / fname) for split, fname in SPLIT_FILES.items()}
    problems, labels = _validate(dfs)
    manifest["splits"] = {k: len(v) for k, v in dfs.items()}
    manifest["labels"] = labels
    manifest["columns"] = list(next(iter(dfs.values())).columns)
    if problems:
        raise RuntimeError("CrisisBench validation failed: " + "; ".join(problems))
    config.DATA_DIR.mkdir(parents=True, exist_ok=True)
    with open(config.DATA_DIR / "manifest.json", "w", encoding="utf-8") as f:
        json.dump(manifest, f, indent=2)
    return manifest

